366	///|
367	async fn Progress::line(
368	  self : Progress,
369	  line : String,
370	  statuses~ : Bool,
371	  messages~ : Bool,
372	) -> Unit {
373	  if line.trim() == "" {
374	    return
375	  }
376	  let event = @json.parse(line) catch { _ => Json::null() }
377	  if field(event, "kind") == Some(Json::string("status")) {
378	    if field(event, "state") == Some(Json::string("failed")) &&
379	      field(event, "error") is Some(error) {
380	      for name in ["message", "hint"] {
381	        if field(error, name) is Some(Json::String(text)) {
382	          self.message(
383	            text,
384	            debug=false,
385	            warning=true,
386	            emit=messages || statuses,
387	          )
388	        }
389	      }
390	    }
391	    if statuses || messages {
392	      self.status(event)
393	    }
394	    return
395	  }
396	  // Result envelopes and arbitrary structured responses are never log text.
397	  if field(event, "kind") == Some(Json::string("result")) {
398	    return
399	  }
400	  if event is Json::Object(_) {
401	    let kind = field(event, "kind")
402	    guard kind == None ||
403	      kind == Some(Json::string("log")) ||
404	      kind == Some(Json::string("error")) else {
405	      return
406	    }
407	    let message = match field(event, "msg") {
408	      Some(value) => Some(value)
409	      None => field(event, "message")
410	    }
411	    guard message is Some(Json::String(text)) else { return }
412	    let level = field(event, "level")
413	    self.message(
414	      text,
415	      debug=level == Some(Json::string("debug")) ||
416	        level == Some(Json::string("trace")),
417	      warning=kind == Some(Json::string("error")) ||
418	        level == Some(Json::string("warn")) ||
419	        level == Some(Json::string("error")),
420	      emit=messages || (statuses && kind != None),
421	    )
422	  } else {
423	    if event != Json::null() {
424	      return
425	    }
426	    // Malformed JSON and binary output are not a safe free-text fallback.
427	    let text = line.trim().to_owned()
428	    if text.has_prefix("{") || text.has_prefix("[") {
429	      self.details_truncated = true
430	      return
431	    }
432	    self.message(
433	      text,
434	      debug=text.contains(" DEBUG ") ||
435	        text.contains(" TRACE ") ||
436	        text.has_prefix("DEBUG ") ||
437	        text.has_prefix("TRACE "),
438	      warning=text.contains(" WARN ") ||
439	        text.contains(" ERROR ") ||
440	        text.has_prefix("WARN ") ||
441	        text.has_prefix("ERROR "),
442	      emit=messages,
443	    )
444	  }
445	}
