  2	fn credential_field(name : String) -> Bool {
  3	  let name = name
  4	    .trim_start(chars="-")
  5	    .to_owned()
  6	    .to_lower()
  7	    .replace_all(old="-", new="_")
  8	  [
  9	    "auth", "authorization", "proxy_authorization", "cookie", "set_cookie", "password",
 10	    "passwd", "token", "access_token", "accesstoken", "refresh_token", "refreshtoken",
 11	    "id_token", "api_key", "apikey", "x_api_key", "credential", "credentials", "secret",
 12	    "client_secret", "clientsecret", "private_key", "privatekey", "aws_secret_access_key",
 13	    "azure_storage_key", "docker_auth_config", "signature", "sig", "x_amz_signature",
 14	    "x_amz_security_token", "x_goog_signature",
 15	  ].contains(name) ||
 16	  [
 17	    "_auth", "_password", "_passwd", "_token", "_secret", "_api_key", "_private_key",
 18	  ]
 19	  .iter()
 20	  .any(suffix => name.has_suffix(suffix))
 21	}
 22	
 23	///|
 24	fn credential_word(c : Char) -> Bool {
 25	  (c >= 'a' && c <= 'z') ||
 26	  (c >= 'A' && c <= 'Z') ||
 27	  (c >= '0' && c <= '9') ||
 28	  c == '_' ||
 29	  c == '-'
 30	}
 31	
 32	///|
 33	fn credential_space(c : Char) -> Bool {
 34	  c == ' ' || c == '\t'
 35	}
 36	
 37	///|
 38	fn credential_end(c : Char) -> Bool {
 39	  credential_space(c) ||
 40	  [',', ';', '&', '#', '"', '\'', '}', ']', '<', '>'].contains(c)
 41	}
 42	
 43	///|
 44	fn character_text(chars : Array[Char], start : Int32, end : Int32) -> String {
 45	  let buffer = @buffer.Buffer(size_hint=end - start)
 46	  for i in start..<end {
 47	    buffer.write_char_utf8(chars[i])
 48	  }
 49	  @utf8.decode_lossy(buffer.to_bytes())
 50	}
 51	
 52	///|
 53	fn credential_hex(c : Char) -> Int32? {
 54	  match c {
 55	    '0'..<='9' => Some(c.to_int() - '0'.to_int())
 56	    'a'..<='f' => Some(c.to_int() - 'a'.to_int() + 10)
 57	    'A'..<='F' => Some(c.to_int() - 'A'.to_int() + 10)
 58	    _ => None
 59	  }
 60	}
 61	
 62	///|
 63	fn credential_parameter(name : String) -> String {
 64	  let chars = name.iter().to_array()
 65	  let buffer = @buffer.Buffer(size_hint=name.length())
 66	  let mut i = 0
 67	  while i < chars.length() {
 68	    if chars[i] == '%' &&
 69	      i + 2 < chars.length() &&
 70	      credential_hex(chars[i + 1]) is Some(hi) &&
 71	      credential_hex(chars[i + 2]) is Some(lo) {
 72	      buffer.write_char_utf8((hi * 16 + lo).unsafe_to_char())
 73	      i += 3
 74	    } else {
 75	      buffer.write_char_utf8(chars[i])
 76	      i += 1
 77	    }
 78	  }
 79	  @utf8.decode_lossy(buffer.to_bytes())
 80	}
 81	
 82	///|
 83	fn redact_credentials(text : String) -> String {
 84	  let chars = text.iter().to_array()
 85	  let buffer = @buffer.Buffer(size_hint=text.length())
 86	  let mut i = 0
 87	  let mut url = false
 88	  while i < chars.length() {
 89	    if credential_space(chars[i]) || ['"', '\''].contains(chars[i]) {
 90	      url = false
 91	    }
 92	    if chars[i] == ':' &&
 93	      i + 2 < chars.length() &&
 94	      chars[i + 1] == '/' &&
 95	      chars[i + 2] == '/' {
 96	      url = true
 97	      buffer.write_string_utf8("://")
 98	      i += 3
 99	      let mut end = i
100	      let mut user_end = None
101	      while end < chars.length() &&
102	            !credential_end(chars[end]) &&
103	            !['/', '?'].contains(chars[end]) {
104	        if chars[end] == '@' {
105	          user_end = Some(end)
106	        }
107	        end += 1
108	      }
109	      if user_end is Some(end) {
110	        buffer.write_string_utf8("[redacted]@")
111	        i = end + 1
112	      }
113	      continue
114	    }
115	    if url && ['?', '&'].contains(chars[i]) {
116	      let start = i
117	      i += 1
118	      while i < chars.length() && !credential_end(chars[i]) && chars[i] != '=' {
119	        i += 1
120	      }
121	      let name = credential_parameter(character_text(chars, start + 1, i))
122	      if i < chars.length() && chars[i] == '=' {
123	        i += 1
124	        buffer.write_string_utf8(character_text(chars, start, i))
125	        if credential_field(name) || name.to_lower() == "key" {
126	          while i < chars.length() && !credential_end(chars[i]) {
127	            i += 1
128	          }
129	          buffer.write_string_utf8("[redacted]")
130	          if i < chars.length() &&
131	            chars[i] == ']' &&
132	            i >= 9 &&
133	            character_text(chars, i - 9, i + 1) == "[redacted]" {
134	            i += 1
135	          }
136	        }
137	      } else {
138	        buffer.write_string_utf8(character_text(chars, start, i))
139	      }
140	      continue
141	    }
142	    if credential_word(chars[i]) && (i == 0 || !credential_word(chars[i - 1])) {
143	      let start = i
144	      let mut end = i
145	      while end < chars.length() && credential_word(chars[end]) {
146	        end += 1
147	      }
148	      let word = character_text(chars, start, end)
149	      let lower = word.to_lower()
150	      if [
151	          "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "sk-", "age-secret-key-",
152	        ]
153	        .iter()
154	        .any(prefix => lower.has_prefix(prefix)) ||
155	        (word.has_prefix("eyJ") && end < chars.length() && chars[end] == '.') {
156	        while end < chars.length() && !credential_end(chars[end]) {
157	          end += 1
158	        }
159	        buffer.write_string_utf8("[redacted]")
160	        i = end
161	        continue
162	      }
163	      let mut separator = end
164	      if separator < chars.length() && ['"', '\''].contains(chars[separator]) {
165	        separator += 1
166	      }
167	      while separator < chars.length() && credential_space(chars[separator]) {
168	        separator += 1
169	      }
170	      let mut previous = start
171	      while previous > 0 && credential_space(chars[previous - 1]) {
172	        previous -= 1
173	      }
174	      let field_start = previous == 0 ||
175	        [';', ',', '{', '"', '\'', '?', '&'].contains(chars[previous - 1])
176	      let option = word.has_prefix("--")
177	      let prose_credential = ["credential", "credentials"].contains(lower) &&
178	        !field_start
179	      let assignment = separator < chars.length() &&
180	        (
181	          chars[separator] == '=' ||
182	          (chars[separator] == ':' && !prose_credential)
183	        )
184	      if credential_field(word) && (assignment || (option && separator > end)) {
185	        let mut value = if assignment { separator + 1 } else { separator }
186	        while value < chars.length() && credential_space(chars[value]) {
187	          value += 1
188	        }
189	        buffer.write_string_utf8(character_text(chars, start, value))
190	        let quoted_key = start > 0 &&
191	          end < chars.length() &&
192	          ['"', '\''].contains(chars[start - 1]) &&
193	          chars[start - 1] == chars[end]
194	        if ["cookie", "set-cookie", "--cookie"].contains(lower) && !quoted_key {
195	          buffer.write_string_utf8("[redacted]")
196	          i = chars.length()
197	        } else if value + 10 <= chars.length() &&
198	          character_text(chars, value, value + 10) == "[redacted]" {
199	          buffer.write_string_utf8("[redacted]")
200	          i = value + 10
201	        } else if value < chars.length() && ['"', '\''].contains(chars[value]) {
202	          let quote = chars[value]
203	          buffer.write_char_utf8(quote)
204	          value += 1
205	          while value < chars.length() && chars[value] != quote {
206	            if chars[value] == '\\' && value + 1 < chars.length() {
207	              value += 1
208	            }
209	            value += 1
210	          }
211	          buffer.write_string_utf8("[redacted]")
212	          i = value
213	        } else {
214	          let mut value_end = value
215	          while value_end < chars.length() && !credential_end(chars[value_end]) {
216	            value_end += 1
217	          }
218	          let scheme = character_text(chars, value, value_end).to_lower()
219	          if scheme == "bearer" || scheme == "basic" {
220	            while value_end < chars.length() &&
221	                  credential_space(chars[value_end]) {
222	              value_end += 1
223	            }
224	            buffer.write_string_utf8(character_text(chars, value, value_end))
225	            value = value_end
226	            while value_end < chars.length() &&
227	                  !credential_end(chars[value_end]) {
228	              value_end += 1
229	            }
230	          }
231	          if value + 10 <= chars.length() &&
232	            character_text(chars, value, value + 10) == "[redacted]" {
233	            value_end = value + 10
234	          }
235	          if value_end > value {
236	            buffer.write_string_utf8("[redacted]")
237	          }
238	          i = value_end
239	        }
240	        continue
241	      }
242	      buffer.write_string_utf8(word)
243	      i = end
244	      continue
245	    }
246	    buffer.write_char_utf8(chars[i])
247	    i += 1
248	  }
249	  @utf8.decode_lossy(buffer.to_bytes())
250	}
