252	///|
253	fn Progress::safe_message(self : Progress, text : String) -> String? {
254	  guard terminal_text(text) is Some(text) else { return None }
255	  let lower = text.to_lower()
256	  if lower.contains("-----begin ") && lower.contains("private key-----") {
257	    self.private_key = REDACTED ")
258	    return Some("[private key redacted]")
259	  }
260	  if self.private_key {
261	    if lower.contains("-----end ") && lower.contains("private key-----") {
262	      self.private_key = false
263	    }
264	    return None
265	  }
266	  let mut safe = text
267	  for secret in self.secrets {
268	    safe = safe.replace_all(old=secret, new="[redacted]")
269	  }
270	  safe = redact_credentials(safe)
271	  if safe.length() > 1024 {
272	    safe = safe[:1024].to_owned() + "… [truncated]"
273	    self.details_truncated = true
274	  }
275	  Some(safe)
276	}

