    57	///|
    58	async fn adapter_executable() -> String {
    59	  let name = @env.args()[0]
    60	  if name.contains("/") {
    61	    return @fs.realpath(name)
    62	  }
    63	  for directory in @env.get_env_var("PATH").unwrap_or("").split(":") {
    64	    let path = directory.to_owned() + "/" + name
    65	    if @fs.exists(path) {
    66	      return @fs.realpath(path)
    67	    }
    68	  }
    69	  raise AdapterError("Adapter executable is unavailable for tunnel recovery")
    70	}
