    88	  let target = directory + "/ssh-proxy-adapter"
    89	  let executable = adapter_executable()
    90	  if executable == target {
    91	    return target
    92	  }
    93	  save_diagnostic("ssh-proxy-launcher", "started")
    94	  errdefer save_diagnostic(
    95	    "ssh-proxy-launcher",
    96	    "failed",
    97	    error_type="filesystem",
