   160	///|
   161	async fn prepare_socket_directory(state : Json, directory : String) -> Unit {
   162	  let previous = required(state, "socketDirectory")
   163	  @fs.mkdir(previous, permission=0o700, allow_exist=true) catch {
   164	    error => {
   165	      let replacement = socket_directory(workspace_environment(state))
   166	      errdefer (@fs.rmdir(replacement) catch { _ => () })
   167	      let saved = @json.parse(@fs.read_file(directory + "/state.json").text())
   168	      guard field(saved, "workspaceUid") == field(state, "workspaceUid") &&
   169	        field(saved, "socketDirectory") == Some(Json::string(previous)) else {
   170	        raise AdapterError("SSH socket ownership changed")
   171	      }
   172	      set_field(saved, "socketDirectory", Json::string(replacement))
   173	      publish_file(directory + "/state.json", saved.stringify())
   174	      set_field(state, "socketDirectory", Json::string(replacement))
   175	      save_diagnostic(
   176	        "orca-tunnel",
   177	        "retry",
   178	        tunnel_directory=directory,
   179	        error_type="control_socket",
   180	        error_message=redact_credentials(error.to_string()),
   181	        evidence={ "previous": previous, "replacement": replacement },
   182	        recording=workspace_recording(state),
   183	      )
   184	    }
   185	  }
   186	  guard validate_socket_directory(
   187	      @utf8.encode(required(state, "socketDirectory") + "\u0000"),
   188	    ) ==
   189	    0 else {
   190	    raise AdapterError("Invalid SSH socket directory ownership or permissions")
   191	  }
   192	}
