   146	fn socket_directory(environment : Map[String, String]) -> String raise {
   147	  let buffer = Bytes::make(4096, 0)
   148	  let length = create_socket_directory(
   149	    buffer,
   150	    buffer.length(),
   151	    @utf8.encode(environment.get("XDG_RUNTIME_DIR").unwrap_or("") + "\u0000"),
   152	    @utf8.encode(environment.get("TMPDIR").unwrap_or("") + "\u0000"),
   153	  )
   154	  guard length > 0 else {
   155	    raise AdapterError("Cannot create SSH socket directory")
   156	  }
   157	  @utf8.decode(buffer[:length])
