name: E2E
on:
  pull_request:
  push:
    branches: [main]
  workflow_dispatch:
permissions:
  contents: read
jobs:
  e2e:
    timeout-minutes: 45
    strategy:
      fail-fast: false
      matrix:
        os: [ubuntu-24.04, ubuntu-24.04-arm]
        provider: [docker, podman, microsandbox]
        exclude:
          - os: ubuntu-24.04-arm
            provider: microsandbox
    runs-on: ${{ matrix.os }}
    steps:
      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6.1.0
        with:
          persist-credentials: false
      - uses: jdx/mise-action@3c2e0cf82a5b2e5249f0d3635a4d83d0ae861518 # v4.2.5
        with:
          version: 2026.10.8
      - name: Prepare provider and Electron dependencies
        run: mise run test:e2e:prepare-ci -- "${{ matrix.provider }}"
      - name: Exercise pinned Orca with the adapter
        env:
          GITHUB_TOKEN: ${{ github.token }}
        run: xvfb-run -a mise run test:e2e -- --provider "${{ matrix.provider }}"
      - name: Preserve sanitized run result
        if: always()
        uses: actions/upload-artifact@ea165f8d65b6e75b540449e92b4886f43607fa02 # v4.6.2
        with:
          name: e2e-${{ matrix.os }}-${{ matrix.provider }}
          path: .e2e/*/result.json
          include-hidden-files: true
          if-no-files-found: warn
